def solve(inputs):
    X = inputs['X'] & 0xFFFFFFFF
    for _ in range(inputs['K']):
        X ^= (X << inputs['A']) & 0xFFFFFFFF
        X ^= (X >> inputs['B']) & 0xFFFFFFFF
        X ^= (X << inputs['C']) & 0xFFFFFFFF
    return float(X)

